/* Shared transaction list and details; provider records are explicit local simulations. */
const ui113={tab:'transactions',q:'',kind:'all',status:'all',attention:false,from:'',to:'',open:null};
const paymentNames113=localizedNames113({pending:'Menunggu pembayaran',paid:'Berhasil',expired:'Kedaluwarsa',failed:'Gagal'}),kindNames113=localizedNames113({plan:'Paket',credits:'Kredit',service:'Layanan'}),refundNames113=localizedNames113({review:'Dalam pemeriksaan',info:'Perlu informasi',approved:'Siap dikembalikan',processing:'Pengembalian diproses',done:'Dana dikembalikan',closed:'Pemeriksaan selesai'});
const eventNames113=localizedNames113({created:'Pembelian dibuat',paid:'Pembayaran berhasil',fulfilled:'Pembelian terpenuhi',retry:'Pembayaran baru dibuat',synced:'Pembayaran dicocokkan',review:'Pemeriksaan diajukan',claim:'Penanganan dimulai',assign:'Penanganan dialihkan','request-info':'Informasi diminta',respond:'Informasi dikirim',resolve:'Pemeriksaan diselesaikan','refund-open':'Pengembalian ditinjau','refund-info':'Rekening tujuan diminta','refund-destination':'Rekening dikonfirmasi','refund-approve':'Pengembalian disetujui','refund-process':'Pengembalian diproses','refund-done':'Dana dikembalikan','refund-close':'Pemeriksaan pengembalian selesai'});
const B113=(label,action,id='',cls='')=>`<button type="button" class="btn ${cls}" data-t113="${action}" data-id="${E(id)}">${tr113(label)}</button>`;
function can113(){return isLabel10()||ten.role==='super'||permission('finance')!=='none'}
function write113(){return ten.role==='super'||ten.role==='admin'&&permission('finance')==='direct'&&!['read','blocked'].includes(access8('payments'))}
function actor113(){return {...actor11(),view:can113(),write:write113()}}
function rows113(){return can113()?Transactions113.init(ten).orders.filter(o=>Transactions113.visible(actor113(),o)):[]}
function order113(id){return rows113().find(o=>o.id===id)}
function title113(o){return o.kind==='credits'?T('Pembelian ','Purchase ')+o.credits+' '+T('kredit','credits'):o.kind==='plan'?(o.plan||o.title)+' · '+T(o.period==='month'?'Bulanan':'Tahunan',o.period==='month'?'Monthly':'Annual'):o.title;}
function name113(id){return RM10.getMember(ten,id)?.name||people.find(p=>p.id===id)?.name||id||tr113('Belum ditetapkan')}
function atomic113(action,p){const before=structuredClone(ten);try{if(action==='assign'&&!people.some(x=>x.id===p.handler&&(x.super||data.roles.find(r=>r.id===data.assignments[x.id])?.rules.finance==='direct')))throw Error(tr113('Pilih petugas dengan akses tindakan pembayaran.'));const result=Transactions113.act(ten,actor113(),action,p);save10();return result}catch(err){Object.keys(ten).forEach(k=>delete ten[k]);Object.assign(ten,before);throw err}}
function route113(tab='transactions'){document.querySelector('#transaction-drawer113')?.close();closeModal();closePop();ui113.tab=isLabel10()&&tab==='reconcile'?'transactions':tab;module102('payments');render()}
function paymentTag113(o){return statusBadge111(paymentNames113[o.payment],o.payment==='paid'?'green':o.payment==='failed'?'red':o.payment==='pending'?'blue':'neutral')}
function result113(o){if(o.payment!=='paid')return tr113('Pembelian belum dipenuhi');if(!o.fulfilled)return tr113('Perlu tindak lanjut');if(o.kind==='credits')return (o.credited||o.credits+o.bonus)+tr113(' kredit telah ditambahkan');if(o.kind==='plan')return o.activationWaiting?tr113('Menunggu aktivasi akun'):tr113('Paket aktif');return tr113('Permintaan telah diterima')}
function filtered113(){const q=ui113.q.trim().toLowerCase(),from=ui113.from?Date.parse(ui113.from+'T00:00:00+07:00'):-Infinity,to=ui113.to?Date.parse(ui113.to+'T23:59:59+07:00'):Infinity;return rows113().filter(o=>(ui113.kind==='all'||o.kind===ui113.kind)&&(ui113.status==='all'||o.payment===ui113.status)&&(!ui113.attention||!!Transactions113.issue(ten,o))&&(ui113.tab==='reconcile'||o.created>=from&&o.created<=to)&&[o.id,o.title,name113(o.account),...o.attempts.map(a=>a.id)].join(' ').toLowerCase().includes(q))}
function notice113(){return `<p class="sample111 simulation113">${icon('info')}<span>${tr113("Pratinjau V11.3 · pembayaran dan pengembalian disimulasikan. Kebijakan kelayakan pengembalian masih perlu ditetapkan.")}</span></p>`}
function row113(o){return `<article class="transaction-row113"><div class="purchase113"><span class="purchase-icon113">${icon(o.kind==='credits'?'wallet':o.kind==='plan'?'shield':'release')}</span><div><strong>${E(title113(o))}</strong><small>${E(o.id)} · ${kindNames113[o.kind]}${!isLabel10()?' · '+E(name113(o.account)):''}</small></div></div><div><span>${date10(o.created)}</span><small>${date10(o.created,true).split(' ').slice(-1)[0]} WIB</small></div><div><strong>${money10(o.amount)}</strong><small>${E(o.quantity)} ${o.kind==='credits'?tr113('kredit pembelian'):o.kind==='service'?tr113('satuan'):tr113('paket')}</small></div><div>${paymentTag113(o)}<small class="${o.payment==='paid'&&!o.fulfilled?'mustard113':''}">${E(result113(o))}</small></div>${B113('↗','detail',o.id,'arrow107')}</article>`}
function toolbar113(){return `<div class="tools111 toolbar113"><input type="search" id="search113" value="${E(ui113.q)}" placeholder="${tr113("Cari pembelian, label, atau nomor transaksi…")}" aria-label="${tr113("Cari transaksi")}"><select id="kind113" aria-label="${tr113("Jenis pembelian")}"><option value="all">${tr113("Semua pembelian")}</option>${Object.entries(kindNames113).map(([id,n])=>`<option value="${id}" ${ui113.kind===id?'selected':''}>${n}</option>`).join('')}</select><select id="status113" aria-label="${tr113("Status pembayaran")}"><option value="all">${tr113("Semua pembayaran")}</option>${Object.entries(paymentNames113).map(([id,n])=>`<option value="${id}" ${ui113.status===id?'selected':''}>${n}</option>`).join('')}</select><label>${tr113("Dari")}<input type="date" id="from113" value="${ui113.from}"></label><label>${tr113("Sampai")}<input type="date" id="to113" value="${ui113.to}"></label><label><input type="checkbox" id="attention113" ${ui113.attention?'checked':''}>${tr113("Perlu tindak lanjut")}</label>${B113(tr113('Reset filter'),'reset','','text')}</div>`}
function page113(){if(!can113())return denied9();const all=rows113(),rows=filtered113(),cases=Transactions113.init(ten).refunds.filter(r=>rows.some(o=>o.id===r.order)),issues=all.filter(o=>Transactions113.issue(ten,o)),pending=all.filter(o=>o.payment==='pending');return `<div class="page113"><header class="head107"><div><span class="eyebrow107">${tr113("PEMBELIAN & PEMBAYARAN")}</span><h1>${tr113("Transaksi")}</h1><p>${tr113("Pembayaran yang jelas. Setiap pembelian terselesaikan.")}</p></div>${B113(tr113('Panduan transaksi'),'guide','','text')}</header>${notice113()}<div class="summary113">${[['pending',tr113('Menunggu pembayaran'),pending.length,tr113('Pembayaran yang masih tersedia')],['paid',tr113('Pembayaran berhasil'),all.filter(o=>o.payment==='paid').length,tr113('Terpisah dari proses layanan')],['attention',tr113('Perlu tindak lanjut'),issues.length,tr113('Pemeriksaan dan penyelesaian')]].map(([id,title,note,sub],i)=>`<button class="summary-card113 ${i===0?'brand113':''}" data-t113="summary" data-id="${id}"><span>${title}</span><strong>${note}</strong><small>${sub}</small>${icon('arrow')}</button>`).join('')}</div><nav class="tabs" data-switch-key105="commerce113-tabs">${[['transactions',tr113('Transaksi')],['refunds',tr113('Pengembalian Dana')],...(!isLabel10()?[['reconcile',tr113('Pencocokan Pembayaran')]]:[])].map(([id,n])=>B113(n,'tab',id,ui113.tab===id?'active':'text')).join('')}</nav>${toolbar113()}${ui113.from&&ui113.to&&ui113.from>ui113.to?`<p class="error11">${tr113("Tanggal mulai harus sebelum tanggal akhir.")}</p>`:''}${ui113.tab==='transactions'?`<section class="panel111 transaction-list113"><div class="list-head113"><span>${tr113("PEMBELIAN")}${!isLabel10()?' / LABEL':''}</span><span>${tr113("TANGGAL")}</span><span>${tr113("NOMINAL")}</span><span>${tr113("PEMBAYARAN / HASIL")}</span><span></span></div>${rows.map(row113).join('')||empty113(tr113('Belum ada transaksi pada daftar ini'),tr113('Pembelian paket, kredit, dan layanan akan tercatat di sini.'))}</section><small class="footnote11">${rows.length} ${tr113("transaksi · hasil pembelian dan saldo tersedia ditampilkan terpisah.")}</small>`:ui113.tab==='refunds'?`<section class="panel111 transaction-list113">${cases.map(r=>{const o=order113(r.order);return `<article class="refund-row113"><div><small>${r.id} · ${E(o.id)}</small><strong>${E(title113(o))}</strong><span>${E(r.reason)}${!isLabel10()?' · '+E(name113(o.account)):''}</span></div><div>${statusBadge111(refundNames113[r.status],r.status==='done'?'green':r.status==='closed'?'neutral':'mustard')}<small>${r.amount?money10(r.amount):tr113('Nominal belum disetujui')}</small></div>${B113('↗','detail',o.id,'arrow107')}</article>`}).join('')||empty113(tr113('Belum ada kasus pengembalian'),tr113('Kasus dibuka dari transaksi asal setelah pembayaran diperiksa.'))}</section>`:reconcile113(rows)}</div>`}
function empty113(title,text){return `<div class="empty113"><span>${icon('wallet')}</span><h2>${title}</h2><p>${text}</p></div>`}
function reconcile113(list){const m=Transactions113.init(ten),c=m.check;list=list.filter(o=>Transactions113.windowOrders(ten,c.from??-Infinity,c.to??Infinity).some(x=>x.id===o.id));const filtered=c.rows.filter(r=>!r.order||list.some(o=>o.id===r.order));return `<section class="panel111"><div class="head107"><div><h2>${tr113("Pencocokan Pembayaran")}</h2><p>${tr113("Bandingkan referensi, nominal, dan status dari dua sumber.")}</p></div><div class="actions107">${B113(tr113('Periksa pembayaran'),'check','','primary')}${B113(tr113('Simulasi data tidak tersedia'),'check-fail','','text')}</div></div><p class="muted113">${c.at?tr113('Pemeriksaan terakhir: ')+date10(c.at,true)+' WIB':tr113('Belum ada pemeriksaan.')}</p>${c.ok===false?`<div class="notice111"><strong>${tr113("Belum dapat diperiksa")}</strong><p>${E(tr113(c.error))}</p><small>${tr113("Hasil ini tidak berarti semua pembayaran sesuai.")}</small></div>`:c.ok===null?empty113(tr113('Mulai pemeriksaan pembayaran'),tr113('Gunakan rentang tanggal di atas, lalu periksa data simulasi penyedia.')): `<div class="reconcile-summary113"><div><small>${tr113("Sesuai")}</small><strong>${list.filter(o=>!c.rows.some(r=>r.order===o.id)).length}</strong></div><div><small>${tr113("Perlu diperiksa")}</small><strong>${new Set(filtered.map(x=>x.order||x.provider)).size}</strong></div></div>${filtered.map(r=>`<article class="refund-row113"><div><strong>${E(tr113(r.text))}</strong><small>${E(r.order||r.provider)}${r.order?' · '+E(name113(order113(r.order)?.account)):''}</small></div>${statusBadge111(tr113('Perlu diperiksa'),'mustard')}${B113('↗',r.order?'detail':'provider',r.order||r.provider,'arrow107')}</article>`).join('')||`<p>${tr113("Catatan pembayaran dalam periode pemeriksaan sudah sesuai.")}</p>`}`}<p class="sample111">${tr113("Pemeriksaan menggunakan catatan simulasi lokal. Tidak menghubungi penyedia pembayaran atau memindahkan dana.")}</p></section>`}
function copy113(text){return B113(tr113('Salin'),'copy',text,'text copy113')}
function detailsActions113(o){const a=Transactions113.attempt(o),r=Transactions113.pendingRefund(ten,o);if(isLabel10()){if(r?.status==='info')return B113(tr113('Konfirmasikan rekening tujuan'),'refund-destination',o.id,'primary');if(o.case?.status==='info')return B113(tr113('Kirim informasi'),'respond',o.id,'primary');if(o.payment==='pending')return B113(tr113('Lanjutkan pembayaran'),'simulate-pay',o.id,'primary')+B113(tr113('Saya sudah membayar'),'check-own',o.id,'text');if(['expired','failed'].includes(o.payment))return B113(tr113('Periksa pembayaran'),'check-own',o.id,'primary')+B113(tr113('Buat pembayaran baru'),'retry',o.id,'text');if(o.payment==='paid'&&!o.fulfilled)return !o.case||o.case.status==='resolved'?B113(tr113('Ajukan pemeriksaan'),'review',o.id,'primary'):'';return ''}if(!write113())return `<p class="muted113">${tr113("Akses lihat · tindakan membutuhkan kewenangan pembayaran.")}</p>`;let h='';if(Transactions113.issue(ten,o)&&!o.handler)h+=B113(tr113('Ambil Penanganan'),'claim',o.id,'primary');if(o.handler&&o.handler!==state.user&&ten.role!=='super')return h+`<p>${tr113("Ditangani")} `+E(name113(o.handler))+'.</p>';if(Transactions113.issue(ten,o)&&ten.role==='super')h+=B113(tr113('Alihkan Penanganan'),'assign',o.id,'text');if(o.payment!=='paid'&&Transactions113.init(ten).provider.some(p=>p.order===o.id&&p.status==='paid'))h+=B113(tr113('Perbarui dari penyedia'),'sync',o.id,'primary');if(o.payment==='paid'&&!o.fulfilled&&!r&&(o.handler===state.user||ten.role==='super'))h+=B113(tr113('Selesaikan pembelian'),'fulfill',o.id,'primary');if(!r){if(Transactions113.received(ten,o)>Transactions113.refunded(ten,o))h+=B113(tr113('Tinjau pengembalian dana'),'refund-open',o.id,'text');if(!o.case||o.case.status==='resolved')h+=B113(tr113('Buka pemeriksaan'),'review',o.id,'text');}if(o.case?.status==='review')h+=B113(tr113('Minta informasi'),'request-info',o.id,'text')+B113(tr113('Selesaikan pemeriksaan'),'resolve',o.id,'text');if(r){if(r.status==='review')h+=B113(tr113('Minta rekening tujuan'),'refund-info',o.id,'text')+B113(tr113('Catat penyelesaian tanpa pengembalian'),'refund-close',o.id,'text')+(ten.role==='super'?B113(tr113('Setujui pengembalian'),'refund-approve',o.id,'primary'):'');if(ten.role==='super'&&r.status==='approved')h+=B113(tr113('Mulai pengembalian'),'refund-process',o.id,'primary')+(r.method==='transfer'?B113(tr113('Tandai dana dikembalikan'),'refund-done',o.id,'text'):'');if(ten.role==='super'&&r.status==='processing'){if(r.method==='origin')h+=B113(tr113('Simulasi hasil penyedia'),'simulate-refund',o.id,'text');h+=B113(tr113('Tandai dana dikembalikan'),'refund-done',o.id,'primary')}}return h}
function sourceButton113(o){return o.source?.type==='addon'?B113(tr113('Buka permintaan layanan'),'source',o.id,'text'):o.source?.type==='wami'?B113(tr113('Buka pengajuan WAMI'),'source',o.id,'text'):o.kind==='plan'?B113(o.activationWaiting?tr113('Lengkapi aktivasi'):tr113('Lihat paket'),'source',o.id,'text'):B113(tr113('Buka riwayat kredit'),'source',o.id,'text')}
function resultBlock113(o){if(o.payment!=='paid')return `<p>${tr113("Pembelian akan dipenuhi setelah pembayaran terkonfirmasi.")}</p>`;if(!o.fulfilled)return `<div class="notice111"><strong>${tr113("Pembayaran berhasil")}</strong><p>${tr113("Pembelianmu sedang diselesaikan.")}</p></div>`;if(o.kind==='credits'){const m=RM10.getMember(ten,o.member),b=RM10.balance(ten,m);return `<div class="result-highlight113"><strong>${o.credited||o.credits+o.bonus}</strong><div><h3>${tr113("Kredit telah ditambahkan")}</h3><p>${o.credits} ${tr113("kredit pembelian")}${o.bonus?' + '+o.bonus+tr113(' kredit penawaran'):''}</p></div></div><p>${tr113("Kredit tersedia saat ini:")} <strong>${b.daily+b.paid+b.replacement}</strong></p><small>${tr113("Saldo terkini dapat berubah karena pemakaian. Hasil transaksi tetap tersimpan.")}</small>`}if(o.kind==='plan')return `<div class="notice111"><strong>${o.activationWaiting?tr113('Menunggu aktivasi akun'):tr113('Paket aktif')}</strong><p>${o.activationWaiting?tr113('Masa aktif paket dimulai setelah akunmu diaktifkan.'):date10(o.start)+' — '+date10(o.end)}</p></div><ul>${o.benefits.map(x=>`<li>${E(typeof x==='string'?x:T(x.id,x.en))}</li>`).join('')}</ul>`;const src=o.source,order=src?.type==='addon'?ten.addons111?.orders.find(x=>x.id===src.id):ten.wami11?.orders.find(x=>x.id===src?.id);return `<div class="notice111"><strong>${tr113("Permintaan telah diterima")}</strong><p>${E(order?src.type==='addon'?labels111[order.status]:status11[order.status]?.[0]:tr113('Proses ditelusuri pada pesanan asal.'))}</p></div><p>${tr113("Pembayaran berhasil tidak berarti pengerjaan layanan sudah selesai.")}</p>`}
function detail113(id){const o=order113(id);if(!o)return;document.querySelector('#transaction-drawer113')?.close();closeModal();ui113.open=id;const a=Transactions113.attempt(o),m=Transactions113.init(ten),r=m.refunds.filter(r=>r.order===id),ps=m.provider.filter(p=>p.order===id&&!p.refund);const d=document.createElement('dialog');d.id='transaction-drawer113';d.className='detail-panel111 transaction-drawer113';d.setAttribute('aria-labelledby','transaction-title113');d.innerHTML=`<header class="detail-head111"><div><small>${E(o.id)} ${copy113(o.id)}</small><h2 id="transaction-title113">${tr113("Rincian Transaksi")}</h2></div>${B113('×','close-drawer','','close113')}</header><div class="detail-body111"><section class="transaction-hero113"><span class="purchase-icon113">${icon(o.kind==='credits'?'wallet':o.kind==='plan'?'shield':'release')}</span><div><h2>${E(title113(o))}</h2><p>${E(name113(o.account))} · ${kindNames113[o.kind]}</p></div>${paymentTag113(o)}</section><dl class="facts11"><div><dt>${tr113("Total pembayaran")}</dt><dd>${money10(o.amount)}</dd></div><div><dt>${tr113("Dibuat pada")}</dt><dd>${date10(o.created,true)} WIB</dd></div><div><dt>${tr113("Jumlah / pilihan")}</dt><dd>${o.kind==='plan'?(o.period==='month'?tr113('Bulanan'):tr113('Tahunan')):o.quantity+' '+(o.kind==='credits'?tr113('kredit'):tr113('satuan'))}</dd></div><div><dt>${tr113("Penanggung jawab")}</dt><dd>${E(name113(o.handler))}</dd></div></dl><section class="section11"><h3>${tr113("Ringkasan pembelian")}</h3>${o.quote?.discount?`<div class="order103"><div><span>${tr113("Harga awal")}</span><span>${money10(o.quote.base)}</span></div><div><span>${tr113("Potongan")} ${o.quote.discount}%</span><span>−${money10(o.quote.base-o.amount)}</span></div><div><strong>${tr113("Total pembayaran")}</strong><strong>${money10(o.amount)}</strong></div></div>`:''}${o.items.length?o.items.map(x=>`<p>${E(x.title||x)}</p>`).join(''):''}${o.kind==='plan'&&!o.fulfilled?`<ul>${o.benefits.map(x=>`<li>${E(typeof x==='string'?x:T(x.id,x.en))}</li>`).join('')}</ul>`:''}<small>${tr113("Harga dan isi pesanan disimpan saat pembelian. Pengaturan baru tidak mengubah catatan ini.")}</small></section><section class="section11"><h3>${tr113("Hasil pembelian")}</h3>${resultBlock113(o)}${sourceButton113(o)}</section><section class="section11"><h3>${tr113("Pembayaran")}</h3><p>${tr113("Metode:")} ${E(o.method)}</p>${o.attempts.slice().reverse().map(t=>`<article class="attempt113"><div><strong>${E(t.id)}</strong>${copy113(t.id)}<small>${t.status==='pending'?tr113('Batas pembayaran: ')+date10(t.expires,true)+' WIB':t.paidAt?tr113('Dibayar: ')+date10(t.paidAt,true)+' WIB':tr113('Dibuat: ')+date10(t.created,true)+' WIB'}</small></div>${statusBadge111(paymentNames113[t.status],t.status==='paid'?'green':'neutral')}</article>`).join('')}</section>${!isLabel10()?`<section class="section11"><h3>${tr113("Perbandingan catatan")}</h3><div class="compare113"><article><small>Rilis Musik</small><strong>${money10(o.amount)}</strong><p>${paymentNames113[o.payment]}</p><small>${E(a.id)}</small></article><article><small>${tr113("Penyedia · simulasi")}</small>${ps.length?ps.map(p=>`<div><strong>${money10(p.amount)}</strong><p>${E(paymentNames113[p.status]||p.status)} · ${E(p.currency)}</p><small>${E(p.reference)}<br>${E(p.attempt)}</small></div>`).join(''):`<p>${tr113("Konfirmasi belum tersedia.")}</p>`}</article></div></section>`:''}${o.case?`<section class="section11"><h3>${tr113("Pemeriksaan transaksi")}</h3>${statusBadge111(o.case.status==='info'?tr113('Perlu informasi'):o.case.status==='resolved'?tr113('Pemeriksaan selesai'):tr113('Dalam pemeriksaan'),o.case.status==='resolved'?'green':'mustard')}<p>${E(o.case.reason||'')}</p>${o.case.prompt?`<div class="notice111">${E(o.case.prompt)}</div>`:''}${(o.case.messages||[]).map(x=>`<p>${E(x.note)}<small class="muted113"> · ${date10(x.at,true)}</small></p>`).join('')}</section>`:''}${r.length?`<section class="section11"><h3>${tr113("Pengembalian Dana")}</h3><dl class="facts11"><div><dt>${tr113("Dana diterima")}</dt><dd>${money10(Transactions113.received(ten,o))}</dd></div><div><dt>${tr113("Telah dikembalikan")}</dt><dd>${money10(Transactions113.refunded(ten,o))}</dd></div></dl>${r.map(x=>`<article class="refund-detail113"><small>${x.id}</small>${statusBadge111(refundNames113[x.status],x.status==='done'?'green':'mustard')}<h3>${E(x.reason)}</h3><p>${E(x.note)}</p>${x.prompt?`<p>${E(x.prompt)}</p>`:''}<strong>${x.amount?money10(x.amount):tr113('Nominal belum disetujui')}</strong><p>${x.method==='origin'?tr113('Jalur pembayaran asal'):x.method==='provider'?tr113('Penyedia pembayaran'):tr113('Transfer ke rekening terkonfirmasi')}</p>${x.destination?`<p>${E(x.destination.bank)}<br>${E(x.destination.holder)} · ${isLabel10()||ten.role==='super'?E(x.destination.number):'•••• '+E(x.destination.number.slice(-4))}<small> ${tr113("Dikonfirmasi Label")}</small></p>`:''}${x.disposition?`<p>${tr113("Hasil pemeriksaan pembelian:")} ${E(x.disposition)}</p>`:''}${x.reference?`<small>${E(x.reference)}</small>`:''}${x.completed?`<p>${tr113("Dana dikembalikan pada")} ${date10(x.completed,true)} WIB.</p>`:''}${x.resolution?`<p>${E(x.resolution)}</p>`:''}</article>`).join('')}</section>`:''}<section class="section11"><h3>${tr113("Aktivitas terbaru")}</h3><div class="timeline111">${o.history.filter(h=>!isLabel10()||h.public).slice().reverse().map(h=>`<article class="timeline-row111"><strong>${E(eventNames113[h.key]||h.key)}</strong><p>${E(["created","paid","fulfilled","retry","synced","claim","refund-destination"].includes(h.key)?tr113(h.note):h.note)}</p><small>${date10(h.at,true)} WIB · ${E(name113(h.actor))}</small></article>`).join('')}</div></section>${notice113()}</div><footer class="drawer-actions113">${detailsActions113(o)}</footer>`;document.body.append(d);d.showModal();d.addEventListener('close',()=>{d.remove();ui113.open=null});}
function guide113(){reviewDialogUI(tr113('Panduan Transaksi'),`<div class="form111"><h3>${tr113("Pembayaran dan hasil pembelian adalah dua hal berbeda")}</h3><p>${tr113("Kredit tercatat sebagai pemberian saldo; paket memiliki masa aktif; layanan memiliki proses pengerjaan sendiri. Pembayaran berhasil tidak menandakan layanan telah selesai.")}</p><h3>${tr113("Pemeriksaan tanpa pembayaran ulang")}</h3><p>${tr113("Jika dana sudah terpotong, periksa transaksi yang sama. Pemeriksaan tidak langsung mengubah status menjadi berhasil tanpa konfirmasi.")}</p><h3>${tr113("Pengembalian Dana")}</h3><p>${tr113("Dana dikembalikan setelah pemeriksaan, persetujuan, dan pelaksanaan. Pemberitahuan pengembalian kredit terpisah dari pengembalian uang. Tidak ada pencabutan otomatis atas kredit atau benefit.")}</p><h3>${tr113("Kewenangan")}</h3><p>${tr113("Label: transaksi miliknya. Admin: sesuai izin tindakan pembayaran. Super Admin: persetujuan pengembalian dan pencatatan hasil. Akses lihat tidak memberi kewenangan melakukan perubahan.")}</p><h3>${tr113("Ketentuan yang belum final")}</h3><p>${tr113("Kelayakan pengembalian, perlakuan layanan/kredit yang terpakai, waktu pengembalian, harga, pergantian paket, dan kredit layanan belum menjadi kebijakan operasional.")}</p>${notice113()}${B113(tr113('Tutup'),'close','','primary')}</div>`)}
function form113(action,id){const o=order113(id);if(!o)return;const r=Transactions113.pendingRefund(ten,o);document.querySelector('#transaction-drawer113')?.close();let title='',body='',submit=tr113('Simpan'),checked=`<label class="check11"><input type="checkbox" name="checked" required>${tr113("Data dan tindakan telah saya periksa.")}</label>`,note=`<label>${tr113("Keterangan")}<textarea name="note" rows="3" required minlength="5" maxlength="4000"></textarea></label>`;
if(action==='simulate-pay'){title=tr113('Selesaikan pembayaran');submit=tr113('Simulasikan pembayaran berhasil');body=`<strong class="payment-total113">${money10(o.amount)}</strong><p>${E(title113(o))} · ${E(Transactions113.attempt(o).id)}</p>${notice113()}${checked}`;}
else if(action==='retry'){title=tr113('Buat pembayaran baru');submit=tr113('Buat pembayaran');body=`<strong class="payment-total113">${money10(o.amount)}</strong><p>${E(title113(o))}${tr113(". Ringkasan pembelian tetap sama. Pembayaran sebelumnya tetap tersimpan dalam riwayat.")}</p>${checked}`;}
else if(action==='review'){title=tr113('Ajukan pemeriksaan');submit=tr113('Kirim pemeriksaan');body=`<p>${tr113("Jelaskan masalah pembayaran. Nomor transaksi dan pembelian ikut tercatat.")}</p>`+note;}
else if(action==='claim'){title=tr113('Ambil Penanganan');submit=tr113('Ambil Penanganan');body=`<p>${tr113("Pemeriksaan transaksi ini akan menjadi tanggung jawabmu.")}</p>`;}
else if(action==='assign'){title=tr113('Alihkan Penanganan');body=`<label>${tr113("Petugas")}<select name="handler" required>${people.filter(x=>x.super||data.roles.find(r=>r.id===data.assignments[x.id])?.rules.finance==='direct').map(x=>`<option value="${x.id}">${E(x.name)}</option>`).join('')}</select></label>${note}`;}
else if(action==='fulfill'){title=tr113('Selesaikan pembelian');submit=tr113('Selesaikan pembelian');body=`<p>${E(title113(o))} · ${money10(o.amount)}</p><p>${tr113("Sistem hanya memberikan bagian yang belum terpenuhi. Pembayaran dan pemberian sebelumnya diperiksa kembali.")}</p>${checked}`;}
else if(['request-info','respond','resolve'].includes(action)){title=action==='request-info'?tr113('Minta informasi'):action==='respond'?tr113('Kirim informasi'):tr113('Selesaikan pemeriksaan');body=note;}
else if(action==='refund-open'){title=tr113('Tinjau pengembalian dana');submit=tr113('Buka pemeriksaan');body=`<p>${tr113("Dana diterima:")} <strong>${money10(Transactions113.received(ten,o))}</strong></p><label>${tr113("Alasan")}<select name="reason">${[tr113('Pembayaran ganda'),tr113('Pembayaran setelah kedaluwarsa'),tr113('Pembelian tidak dapat dipenuhi'),tr113('Selisih pembayaran'),tr113('Alasan lain')].map(x=>`<option>${x}</option>`).join('')}</select></label><p>${tr113("Alasan memulai pemeriksaan, bukan persetujuan pengembalian otomatis.")}</p>${note}`;}
else if(action==='refund-info'){title=tr113('Minta konfirmasi rekening tujuan');body=`<p>${tr113("Label mengisi dan mengonfirmasikan rekening untuk pengembalian ini. Rekening royalti tidak digunakan otomatis.")}</p>`+note;}
else if(action==='refund-destination'){title=tr113('Konfirmasikan rekening tujuan');submit=tr113('Kirim konfirmasi');body=`<p>${tr113("Rekening ini hanya digunakan untuk pengembalian pada")} ${E(o.id)}.</p>${directoryBankField('')}<label>${tr113("Nomor rekening")}<input name="number" inputmode="numeric" pattern="[0-9]{6,24}" required></label><label>${tr113("Nama pemilik rekening")}<input name="holder" required maxlength="120"></label>${checked}`;}
else if(action==='refund-approve'){title=tr113('Setujui pengembalian dana');submit=tr113('Setujui pengembalian');body=`<p>${tr113("Batas sisa dana:")} <strong>${money10(Transactions113.received(ten,o)-Transactions113.reserved(ten,o,r.id))}</strong></p><label>${tr113("Nominal pengembalian")}<input type="number" name="amount" min="1" max="${Transactions113.received(ten,o)-Transactions113.reserved(ten,o,r.id)}" step="1" required></label><label>${tr113("Jalur pengembalian")}<select name="method"><option value="origin">${tr113("Jalur pembayaran asal")}</option><option value="transfer" ${r.confirmed?'':'disabled'}>${tr113("Transfer ke rekening terkonfirmasi")}</option></select></label><label>${tr113("Hasil pemeriksaan kredit, benefit, dan layanan")}<textarea name="disposition" required minlength="5" rows="3" placeholder="${tr113("Jelaskan bagian yang sudah diberikan/digunakan dan penyelesaiannya.")}"></textarea></label><p>${tr113("Tindakan ini tidak mencabut kredit atau menghentikan layanan secara otomatis.")}</p>${note}${checked}${notice113()}`;}
else if(action==='refund-process'){title=tr113('Mulai pengembalian');submit=tr113('Catat pengembalian diproses');body=`<strong class="payment-total113">${money10(r.amount)}</strong><label>${tr113("Referensi proses")}<input name="reference" required maxlength="150"></label>${note}${checked}`;}
else if(action==='refund-done'){title=tr113('Tandai dana dikembalikan');submit=tr113('Tandai dana dikembalikan');const at=new Date(ten.now+7*3600000).toISOString().slice(0,16);body=`<strong class="payment-total113">${money10(r.amount)}</strong><label>${tr113("Metode pencatatan")}<select name="method"><option value="${r.method==='transfer'?'manual':'provider'}">${r.method==='transfer'?tr113('Transfer manual terkonfirmasi'):tr113('Konfirmasi penyedia')}</option></select></label><label>${tr113("Referensi pengembalian")}<input name="reference" required maxlength="150" value="${E(r.reference)}"></label><label>${tr113("Dikembalikan pada")}<input type="datetime-local" name="at" value="${at}" max="${at}" required></label>${note}<label class="check11"><input type="checkbox" name="checked" required>${tr113("Dana telah dikembalikan; bukan hanya disetujui atau dikirim untuk diproses.")}</label>${notice113()}`;}
else if(action==='refund-close'){title=tr113('Catat penyelesaian pemeriksaan');body=`<p>${tr113("Jelaskan mengapa pengembalian tidak diperlukan dan bagaimana masalah pembelian terselesaikan.")}</p>`+note;}
else return;reviewDialogUI(title,`<form class="form111" data-form113="${action}" data-id="${o.id}" data-version="${o.version}" data-refund="${r?.id||''}"><h3>${E(title113(o))}</h3>${body}<p class="error11" role="alert"></p><footer class="actions107">${B113(tr113('Kembali'),'detail',o.id,'text')}<button class="btn primary" type="submit">${submit}</button></footer></form>`);}
window.addEventListener('click',async e=>{const b=e.target.closest('[data-t113]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const action=b.dataset.t113,id=b.dataset.id;try{if(action==='route')return route113();if(action==='tab'){ui113.tab=id;return render()}if(action==='summary'){ui113.tab='transactions';ui113.attention=id==='attention';ui113.status=id==='attention'?'all':id;return render()}if(action==='reset'){Object.assign(ui113,{q:'',kind:'all',status:'all',attention:false,from:'',to:''});return render()}if(action==='detail')return detail113(id);if(action==='close-drawer')return document.querySelector('#transaction-drawer113')?.close();if(action==='close')return closeModal();if(action==='guide')return guide113();if(action==='copy'){await copyText120(id);return toast(tr113('Nomor transaksi disalin.'))}if(['check','check-fail'].includes(action)){const from=ui113.from?Date.parse(ui113.from+'T00:00:00+07:00'):-Infinity,to=ui113.to?Date.parse(ui113.to+'T23:59:59+07:00'):Infinity;atomic113('check',{from,to,fail:action==='check-fail'});return render()}if(action==='provider'){if(isLabel10()||!can113())throw Error(tr113('Akses tidak tersedia.'));const p=Transactions113.init(ten).provider.find(x=>x.id===id);return reviewDialogUI(tr113('Pembayaran belum dikenali'),`<div class="form111"><strong>${money10(p.amount)}</strong><p>${E(p.reference)} · ${E(p.currency)}</p><p>${tr113("Belum ditemukan transaksi dengan referensi yang sesuai. Jangan memasangkan hanya berdasarkan nama atau nominal.")}</p>${notice113()}${B113(tr113('Tutup'),'close','','primary')}</div>`)}if(action==='source'){const o=order113(id);document.querySelector('#transaction-drawer113')?.close();if(o.source?.type==='addon')return detail111(o.source.id);if(o.source?.type==='wami')return detail11(o.source.id);if(o.kind==='plan')return o.activationWaiting?activationStep105():plans10();route102('history');return;}if(action==='simulate-refund'){if(ten.role!=='super')throw Error(tr113('Akses tidak tersedia.'));const o=order113(id),r=Transactions113.pendingRefund(ten,o);if(!r||r.status!=='processing'||r.method!=='origin')throw Error(tr113('Pengembalian belum diproses.'));const m=Transactions113.init(ten);if(!m.provider.some(x=>x.refund===r.id))m.provider.push({id:'SIM-REF-'+r.id,order:o.id,refund:r.id,reference:r.reference,amount:r.amount,currency:'IDR',status:'refunded',at:ten.now,simulation:true});save10();toast(tr113('Hasil simulasi penyedia tersedia. Catat penyelesaian setelah diperiksa.'));return detail113(id)}if(action==='check-own'||action==='sync'){const o=order113(id);try{atomic113(action,{id,version:o.version});render();detail113(id);return toast(tr113('Status diperbarui dari konfirmasi pembayaran.'))}catch(err){if(action==='sync')throw err;document.querySelector('#transaction-drawer113')?.close();return reviewDialogUI(tr113('Periksa pembayaran'),`<div class="form111"><p>${tr113("Pembayaranmu belum dapat dikonfirmasi. Jika dana sudah terpotong, ajukan pemeriksaan melalui transaksi ini.")}</p><small>${E(tr113(err.message))}</small>${B113(tr113('Ajukan pemeriksaan'),'review',id,'primary')}${B113(tr113('Kembali'),'detail',id,'text')}</div>`)}}return form113(action,id)}catch(err){toast(tr113(err.message))}},true);
window.addEventListener('input',e=>{if(e.target.id!=='search113')return;ui113.q=e.target.value;const n=e.target.selectionStart;render();const input=document.querySelector('#search113');input?.focus();input?.setSelectionRange(n,n)},true);
window.addEventListener('change',e=>{const x=e.target,keys={kind113:'kind',status113:'status',from113:'from',to113:'to',attention113:'attention'};if(!keys[x.id])return;ui113[keys[x.id]]=x.type==='checkbox'?x.checked:x.value;render()},true);
window.addEventListener('submit',e=>{const f=e.target.closest('[data-form113]');if(!f)return;e.preventDefault();e.stopImmediatePropagation();if(!f.reportValidity())return;const b=f.querySelector('[type=submit]');if(b.disabled)return;b.disabled=true;try{const v=Object.fromEntries(new FormData(f)),p={...v,id:f.dataset.id,version:+f.dataset.version,refund:f.dataset.refund,checked:!!v.checked};if(v.amount)p.amount=Number(v.amount);if(v.holder)p.holder=directoryTitle(v.holder);if(v.bank)p.bank=directoryBankDisplay(v.bank);if(v.at)p.at=Date.parse(v.at+':00+07:00');atomic113(f.dataset.form113,p);closeModal();if(f.dataset.form113==='simulate-pay'){state.page='dashboard';render();reviewDialogUI(tr113('Pembayaran berhasil'),`<div class="reward-popup">${coin104()}<h2>${tr113("Pembayaran diterima.")}</h2><p>${E(result113(order113(p.id)))}</p>${B113(tr113('Buka Dashboard'),'close','','primary')}${B113(tr113('Lihat transaksi'),'detail',p.id,'text')}</div>`)}else{render();detail113(p.id)}toast(tr113('Transaksi diperbarui.'))}catch(err){f.querySelector('.error11').textContent=tr113(err.message);}finally{if(b.isConnected)b.disabled=false}},true);
